//! TimeKit — IANA timezones and civil time, done once, correctly.
//!
//! The engine embeds every canonical zone's *current* POSIX TZ rule
//! string from the IANA database (see zones.rs, generated by
//! tools/gen_zones.py; TZDATA_VERSION names the release) and evaluates
//! transitions from those rules: UTC→local, local→UTC with explicit
//! gap/overlap policy, calendar arithmetic, next-transition lookup,
//! ISO-8601 parsing, and a small formatter. Pure logic, no OS calls
//! except the clock (in [`platform`]).
//!
//! Honest scope: POSIX rules describe the rule set *in force now* —
//! they project correctly into the future and the recent past, but a
//! zone whose rules changed historically (e.g. pre-2007 US dates) will
//! evaluate old instants by today's rules. Full historical TZif data
//! is the roadmap item that removes that caveat.

pub mod ffi;
pub mod platform;
pub mod zones;

pub const VERSION: &str = "0.1.0";
pub const VERSION_MAJOR: u32 = 0;
pub const VERSION_MINOR: u32 = 1;
pub const VERSION_PATCH: u32 = 0;

pub const TK_OK: i32 = 0;
pub const ERR_INVALID_ARG: i32 = 1;
pub const ERR_UNKNOWN_ZONE: i32 = 2;
pub const ERR_GAP: i32 = 3;
pub const ERR_AMBIGUOUS: i32 = 4;
pub const ERR_INTERNAL: i32 = 6;

pub const POLICY_EARLIER: i32 = 0;
pub const POLICY_LATER: i32 = 1;
pub const POLICY_REJECT: i32 = 2;

pub type TResult<T> = Result<T, (i32, String)>;

// ---------- civil calendar ----------

pub fn is_leap(y: i64) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

pub fn days_in_month(y: i64, m: u32) -> u32 {
    match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if is_leap(y) {
                29
            } else {
                28
            }
        }
        _ => 0,
    }
}

/// (year, month, day) → days since 1970-01-01 (Hinnant's algorithm).
pub fn days_from_civil(y: i64, m: u32, d: u32) -> i64 {
    let y_adj = if m <= 2 { y - 1 } else { y };
    let era = if y_adj >= 0 { y_adj } else { y_adj - 399 } / 400;
    let yoe = y_adj - era * 400; // [0, 399]
    let mp = if m > 2 { m - 3 } else { m + 9 } as i64; // Mar=0..Feb=11
    let doy = (153 * mp + 2) / 5 + d as i64 - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146_097 + doe - 719_468
}

/// Days since epoch → (year, month, day).
pub fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = (z - era * 146_097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146_096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = (if mp < 10 { mp + 3 } else { mp - 9 }) as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

/// Weekday for a day count: 0 = Sunday.
pub fn weekday_from_days(z: i64) -> u32 {
    (z + 4).rem_euclid(7) as u32 // 1970-01-01 was a Thursday (4)
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Civil {
    pub year: i64,
    pub month: u32,
    pub day: u32,
    pub hour: u32,
    pub minute: u32,
    pub second: u32,
}

impl Civil {
    pub fn validate(&self) -> TResult<()> {
        if !(1..=12).contains(&self.month)
            || self.day == 0
            || self.day > days_in_month(self.year, self.month)
            || self.hour > 23
            || self.minute > 59
            || self.second > 60
        {
            return Err((ERR_INVALID_ARG, format!("invalid civil time: {self:?}")));
        }
        Ok(())
    }
    /// Seconds since epoch *as if* this were UTC (the wall-clock base).
    pub fn wall_secs(&self) -> i64 {
        days_from_civil(self.year, self.month, self.day) * 86_400
            + self.hour as i64 * 3600
            + self.minute as i64 * 60
            + self.second as i64
    }
}

pub fn civil_from_unix(secs: i64) -> Civil {
    let days = secs.div_euclid(86_400);
    let tod = secs.rem_euclid(86_400);
    let (year, month, day) = civil_from_days(days);
    Civil {
        year,
        month,
        day,
        hour: (tod / 3600) as u32,
        minute: ((tod % 3600) / 60) as u32,
        second: (tod % 60) as u32,
    }
}

// ---------- POSIX TZ rules ----------

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum RuleDay {
    /// Jn: 1..365, Feb 29 never counted.
    JulianNoLeap(u32),
    /// n: 0..365, zero-based day of year (leap day counted).
    DayOfYear(u32),
    /// Mm.w.d: month 1..12, week 1..5 (5 = last), weekday 0..6 (Sun=0).
    MonthWeekDay(u32, u32, u32),
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Rule {
    pub day: RuleDay,
    pub time_secs: i64, // local wall seconds into the day; may be <0 or >=86400
}

#[derive(Clone, Debug, PartialEq)]
pub struct DstRule {
    pub abbr: String,
    pub offset: i64, // UTC offset in seconds
    pub start: Rule,
    pub end: Rule,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Zone {
    pub name: String,
    pub std_abbr: String,
    pub std_offset: i64, // UTC offset in seconds
    pub dst: Option<DstRule>,
}

struct Parser<'a> {
    b: &'a [u8],
    i: usize,
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<u8> {
        self.b.get(self.i).copied()
    }
    fn name(&mut self) -> TResult<String> {
        if self.peek() == Some(b'<') {
            self.i += 1;
            let start = self.i;
            while let Some(c) = self.peek() {
                if c == b'>' {
                    break;
                }
                self.i += 1;
            }
            if self.peek() != Some(b'>') || self.i == start {
                return Err((ERR_INVALID_ARG, "unterminated <zone name>".into()));
            }
            let s = String::from_utf8_lossy(&self.b[start..self.i]).to_string();
            self.i += 1;
            Ok(s)
        } else {
            let start = self.i;
            // POSIX abbreviations outside <...> are letters only. A '+'
            // or '-' here is the offset's sign and must NOT be eaten
            // (e.g. "JST-9" is name JST, offset -9).
            while let Some(c) = self.peek() {
                if c.is_ascii_alphabetic() {
                    self.i += 1;
                } else {
                    break;
                }
            }
            if self.i - start < 1 {
                return Err((ERR_INVALID_ARG, "expected a zone abbreviation".into()));
            }
            Ok(String::from_utf8_lossy(&self.b[start..self.i]).to_string())
        }
    }
    /// POSIX offset: [sign]hh[:mm[:ss]] — sign means *west* of Greenwich,
    /// the inverse of a UTC offset. Returns the UTC offset in seconds.
    fn offset(&mut self) -> TResult<i64> {
        let mut sign: i64 = 1; // POSIX: unsigned = west = negative UTC offset
        match self.peek() {
            Some(b'-') => {
                sign = -1;
                self.i += 1;
            }
            Some(b'+') => {
                self.i += 1;
            }
            _ => {}
        }
        let h = self.number(2)?;
        let mut secs = h * 3600;
        if self.peek() == Some(b':') {
            self.i += 1;
            secs += self.number(2)? * 60;
            if self.peek() == Some(b':') {
                self.i += 1;
                secs += self.number(2)?;
            }
        }
        // west-positive `secs` with sign applied -> convert to UTC offset
        Ok(-sign * secs)
    }
    fn number(&mut self, max_digits: usize) -> TResult<i64> {
        let start = self.i;
        let mut v: i64 = 0;
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() && self.i - start < max_digits {
                v = v * 10 + (c - b'0') as i64;
                self.i += 1;
            } else {
                break;
            }
        }
        if self.i == start {
            return Err((ERR_INVALID_ARG, "expected a number".into()));
        }
        Ok(v)
    }
    fn time_of_day(&mut self) -> TResult<i64> {
        // Called after '/'; sign allowed, magnitude up to 24h+.
        let mut sign: i64 = 1;
        match self.peek() {
            Some(b'-') => {
                sign = -1;
                self.i += 1;
            }
            Some(b'+') => {
                self.i += 1;
            }
            _ => {}
        }
        let h = self.number(3)?;
        let mut secs = h * 3600;
        if self.peek() == Some(b':') {
            self.i += 1;
            secs += self.number(2)? * 60;
            if self.peek() == Some(b':') {
                self.i += 1;
                secs += self.number(2)?;
            }
        }
        Ok(sign * secs)
    }
    fn rule(&mut self) -> TResult<Rule> {
        let day = match self.peek() {
            Some(b'J') => {
                self.i += 1;
                RuleDay::JulianNoLeap(self.number(3)? as u32)
            }
            Some(b'M') => {
                self.i += 1;
                let m = self.number(2)? as u32;
                self.expect(b'.')?;
                let w = self.number(1)? as u32;
                self.expect(b'.')?;
                let d = self.number(1)? as u32;
                RuleDay::MonthWeekDay(m, w, d)
            }
            Some(c) if c.is_ascii_digit() => RuleDay::DayOfYear(self.number(3)? as u32),
            _ => return Err((ERR_INVALID_ARG, "expected a transition rule".into())),
        };
        let time_secs = if self.peek() == Some(b'/') {
            self.i += 1;
            self.time_of_day()?
        } else {
            2 * 3600
        };
        Ok(Rule { day, time_secs })
    }
    fn expect(&mut self, c: u8) -> TResult<()> {
        if self.peek() == Some(c) {
            self.i += 1;
            Ok(())
        } else {
            Err((ERR_INVALID_ARG, format!("expected '{}'", c as char)))
        }
    }
}

pub fn parse_posix_tz(name: &str, tz: &str) -> TResult<Zone> {
    let mut p = Parser {
        b: tz.as_bytes(),
        i: 0,
    };
    let std_abbr = p.name()?;
    let std_offset = p.offset()?;
    let mut dst = None;
    if p.i < p.b.len() && p.peek() != Some(b',') {
        let dst_abbr = p.name()?;
        let dst_offset = if p
            .peek()
            .map(|c| c == b',' || c.is_ascii_digit() || c == b'-' || c == b'+')
            .unwrap_or(false)
            && p.peek() != Some(b',')
        {
            p.offset()?
        } else {
            std_offset + 3600
        };
        p.expect(b',')?;
        let start = p.rule()?;
        p.expect(b',')?;
        let end = p.rule()?;
        dst = Some(DstRule {
            abbr: dst_abbr,
            offset: dst_offset,
            start,
            end,
        });
    }
    Ok(Zone {
        name: name.to_string(),
        std_abbr,
        std_offset,
        dst,
    })
}

pub fn zone_by_name(name: &str) -> TResult<Zone> {
    match zones::ZONES.binary_search_by(|(n, _)| (*n).cmp(name)) {
        Ok(idx) => {
            let (_, rule_idx) = zones::ZONES[idx];
            parse_posix_tz(name, zones::RULES[rule_idx as usize])
        }
        Err(_) => Err((ERR_UNKNOWN_ZONE, format!("unknown zone: {name}"))),
    }
}

// ---------- transition engine ----------

fn rule_day_of_year(rule: &Rule, year: i64) -> i64 {
    match rule.day {
        RuleDay::DayOfYear(n) => n as i64,
        RuleDay::JulianNoLeap(n) => {
            // 1-based, Feb 29 not counted: after Feb, leap years shift by 1.
            let d = n as i64 - 1;
            if is_leap(year) && n > 59 {
                d + 1
            } else {
                d
            }
        }
        RuleDay::MonthWeekDay(m, w, wd) => {
            let first = days_from_civil(year, m, 1);
            let first_wd = weekday_from_days(first) as i64;
            let mut day = first + (wd as i64 - first_wd).rem_euclid(7) + (w as i64 - 1) * 7;
            if w == 5 {
                // Last occurrence: step back a week if we ran past month end.
                let (yy, mm, _) = civil_from_days(day);
                if yy != year || mm != m {
                    day -= 7;
                }
            }
            day - days_from_civil(year, 1, 1)
        }
    }
}

/// UTC instant of a transition in `year`. The rule time is wall time in
/// the offset in effect *before* the transition (`pre_offset`).
fn transition_utc(rule: &Rule, year: i64, pre_offset: i64) -> i64 {
    let jan1 = days_from_civil(year, 1, 1);
    (jan1 + rule_day_of_year(rule, year)) * 86_400 + rule.time_secs - pre_offset
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct ZoneInfo {
    pub offset: i64,
    pub is_dst: bool,
}

impl Zone {
    fn abbr_for(&self, info: ZoneInfo) -> &str {
        if info.is_dst {
            self.dst
                .as_ref()
                .map(|d| d.abbr.as_str())
                .unwrap_or(&self.std_abbr)
        } else {
            &self.std_abbr
        }
    }

    /// State at a UTC instant: evaluate this year's and neighbours'
    /// transitions; the latest one at or before t decides.
    pub fn info_at(&self, unix: i64) -> ZoneInfo {
        let Some(dst) = &self.dst else {
            return ZoneInfo {
                offset: self.std_offset,
                is_dst: false,
            };
        };
        let (uy, _, _) = civil_from_days(unix.div_euclid(86_400));
        let mut best: Option<(i64, bool)> = None; // (instant, is_dst_after)
        for y in (uy - 1)..=(uy + 1) {
            let s = transition_utc(&dst.start, y, self.std_offset);
            let e = transition_utc(&dst.end, y, dst.offset);
            for (t, after_dst) in [(s, true), (e, false)] {
                if t <= unix && best.map(|(bt, _)| t > bt).unwrap_or(true) {
                    best = Some((t, after_dst));
                }
            }
        }
        match best {
            Some((_, true)) => ZoneInfo {
                offset: dst.offset,
                is_dst: true,
            },
            _ => ZoneInfo {
                offset: self.std_offset,
                is_dst: false,
            },
        }
    }

    /// Next transition strictly after `unix`, with the state after it.
    pub fn next_transition(&self, unix: i64) -> Option<(i64, ZoneInfo)> {
        let dst = self.dst.as_ref()?;
        let (uy, _, _) = civil_from_days(unix.div_euclid(86_400));
        let mut best: Option<(i64, bool)> = None;
        for y in (uy - 1)..=(uy + 2) {
            let s = transition_utc(&dst.start, y, self.std_offset);
            let e = transition_utc(&dst.end, y, dst.offset);
            for (t, after_dst) in [(s, true), (e, false)] {
                if t > unix && best.map(|(bt, _)| t < bt).unwrap_or(true) {
                    best = Some((t, after_dst));
                }
            }
        }
        best.map(|(t, after_dst)| {
            (
                t,
                if after_dst {
                    ZoneInfo {
                        offset: dst.offset,
                        is_dst: true,
                    }
                } else {
                    ZoneInfo {
                        offset: self.std_offset,
                        is_dst: false,
                    }
                },
            )
        })
    }

    pub fn to_local(&self, unix: i64) -> (Civil, ZoneInfo, String) {
        let info = self.info_at(unix);
        (
            civil_from_unix(unix + info.offset),
            info,
            self.abbr_for(info).to_string(),
        )
    }

    /// Local wall time → UTC. Returns (unix, flags): flags 0 = unique,
    /// 1 = fell in a gap (shifted per policy), 2 = ambiguous (chose per
    /// policy). POLICY_REJECT turns gaps/overlaps into errors.
    pub fn from_local(&self, wall: Civil, policy: i32) -> TResult<(i64, i32)> {
        wall.validate()?;
        if !(0..=2).contains(&policy) {
            return Err((ERR_INVALID_ARG, format!("unknown policy {policy}")));
        }
        let base = wall.wall_secs();
        let std_cand = base - self.std_offset;
        let std_ok = {
            let i = self.info_at(std_cand);
            !i.is_dst && i.offset == self.std_offset
        };
        let dst_cand = self.dst.as_ref().map(|d| base - d.offset);
        let dst_ok = match (dst_cand, &self.dst) {
            (Some(c), Some(d)) => {
                let i = self.info_at(c);
                i.is_dst && i.offset == d.offset
            }
            _ => false,
        };
        match (std_ok, dst_ok) {
            (true, true) => {
                // Ambiguous (fall overlap): earlier = the DST occurrence.
                let (a, b) = (std_cand, dst_cand.unwrap());
                match policy {
                    POLICY_EARLIER => Ok((a.min(b), 2)),
                    POLICY_LATER => Ok((a.max(b), 2)),
                    _ => Err((
                        ERR_AMBIGUOUS,
                        "local time occurs twice (DST overlap)".into(),
                    )),
                }
            }
            (true, false) => Ok((std_cand, 0)),
            (false, true) => Ok((dst_cand.unwrap(), 0)),
            (false, false) => {
                // Gap (spring forward). EARLIER: pre-transition offset
                // (lands after the gap). LATER: post-transition offset
                // (lands before the gap).
                match policy {
                    POLICY_EARLIER => Ok((std_cand, 1)),
                    POLICY_LATER => Ok((dst_cand.unwrap_or(std_cand), 1)),
                    _ => Err((ERR_GAP, "local time does not exist (DST gap)".into())),
                }
            }
        }
    }
}

// ---------- arithmetic / formatting / parsing ----------

/// Calendar arithmetic in a zone: add years/months (day clamped to the
/// target month), then days and seconds; the wall time is re-resolved
/// with POLICY_EARLIER.
pub fn add_calendar(
    zone: &Zone,
    unix: i64,
    years: i64,
    months: i64,
    days: i64,
    secs: i64,
) -> TResult<i64> {
    let (mut c, _, _) = zone.to_local(unix);
    let total_months = (c.year * 12 + (c.month as i64 - 1)) + years * 12 + months;
    let ny = total_months.div_euclid(12);
    let nm = total_months.rem_euclid(12) as u32 + 1;
    c.year = ny;
    c.month = nm;
    c.day = c.day.min(days_in_month(ny, nm));
    // Fold day/second deltas through the wall representation.
    let wall = c.wall_secs() + days * 86_400 + secs;
    let c2 = civil_from_unix(wall);
    Ok(zone.from_local(c2, POLICY_EARLIER)?.0)
}

/// Format with a small strftime subset: %Y %m %d %H %M %S %z %Z %s %%.
pub fn format(zone: &Zone, unix: i64, fmt: &str) -> String {
    let (c, info, abbr) = zone.to_local(unix);
    let mut out = String::new();
    let mut chars = fmt.chars().peekable();
    while let Some(ch) = chars.next() {
        if ch != '%' {
            out.push(ch);
            continue;
        }
        match chars.next() {
            Some('Y') => out.push_str(&format!("{:04}", c.year)),
            Some('m') => out.push_str(&format!("{:02}", c.month)),
            Some('d') => out.push_str(&format!("{:02}", c.day)),
            Some('H') => out.push_str(&format!("{:02}", c.hour)),
            Some('M') => out.push_str(&format!("{:02}", c.minute)),
            Some('S') => out.push_str(&format!("{:02}", c.second)),
            Some('z') => {
                let o = info.offset;
                out.push_str(&format!(
                    "{}{:02}{:02}",
                    if o < 0 { "-" } else { "+" },
                    o.abs() / 3600,
                    (o.abs() % 3600) / 60
                ))
            }
            Some('Z') => out.push_str(&abbr),
            Some('s') => out.push_str(&unix.to_string()),
            Some('%') => out.push('%'),
            Some(other) => {
                out.push('%');
                out.push(other);
            }
            None => out.push('%'),
        }
    }
    out
}

/// Parse "YYYY-MM-DD[T| ]HH:MM[:SS][.fff][Z|±HH:MM|±HHMM|±HH]" or a
/// bare date (midnight UTC) into Unix seconds.
pub fn parse_iso(s: &str) -> TResult<i64> {
    let s = s.trim();
    let b = s.as_bytes();
    if b.len() < 10 {
        return Err((ERR_INVALID_ARG, "too short for ISO-8601".into()));
    }
    let num = |from: usize, len: usize| -> TResult<i64> {
        let mut v: i64 = 0;
        for k in 0..len {
            let c = b.get(from + k).copied().unwrap_or(b' ');
            if !c.is_ascii_digit() {
                return Err((ERR_INVALID_ARG, "expected digits in ISO-8601".into()));
            }
            v = v * 10 + (c - b'0') as i64;
        }
        Ok(v)
    };
    let year = num(0, 4)?;
    if b[4] != b'-' || b[7] != b'-' {
        return Err((ERR_INVALID_ARG, "expected YYYY-MM-DD".into()));
    }
    let month = num(5, 2)? as u32;
    let day = num(8, 2)? as u32;
    let mut idx = 10;
    let (mut hh, mut mm, mut ss) = (0, 0, 0);
    if idx < b.len() && (b[idx] == b'T' || b[idx] == b' ') {
        idx += 1;
        if idx + 5 > b.len() {
            return Err((ERR_INVALID_ARG, "truncated time".into()));
        }
        hh = num(idx, 2)?;
        if b[idx + 2] != b':' {
            return Err((ERR_INVALID_ARG, "expected HH:MM".into()));
        }
        mm = num(idx + 3, 2)?;
        idx += 5;
        if idx < b.len() && b[idx] == b':' {
            ss = num(idx + 1, 2)?;
            idx += 3;
        }
        if idx < b.len() && b[idx] == b'.' {
            idx += 1;
            while idx < b.len() && b[idx].is_ascii_digit() {
                idx += 1;
            }
        }
    }
    let civil = Civil {
        year,
        month,
        day,
        hour: hh as u32,
        minute: mm as u32,
        second: ss as u32,
    };
    civil.validate()?;
    let mut base = civil.wall_secs();
    // Zone designator:
    if idx < b.len() {
        match b[idx] {
            b'Z' | b'z' => {}
            b'+' | b'-' => {
                let sign = if b[idx] == b'-' { -1 } else { 1 };
                let rest = &s[idx + 1..];
                let digits: String = rest.chars().filter(|c| *c != ':').collect();
                if digits.len() < 2 || !digits.chars().all(|c| c.is_ascii_digit()) {
                    return Err((ERR_INVALID_ARG, "bad UTC offset in ISO-8601".into()));
                }
                let oh: i64 = digits[..2]
                    .parse()
                    .map_err(|_| (ERR_INVALID_ARG, "bad offset".into()))?;
                let om: i64 = if digits.len() >= 4 {
                    digits[2..4]
                        .parse()
                        .map_err(|_| (ERR_INVALID_ARG, "bad offset".into()))?
                } else {
                    0
                };
                base -= sign * (oh * 3600 + om * 60);
            }
            _ => return Err((ERR_INVALID_ARG, "unexpected trailing characters".into())),
        }
    }
    Ok(base)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn chicago() -> Zone {
        zone_by_name("America/Chicago").unwrap()
    }

    #[test]
    fn zone_table_sane() {
        assert!(zones::ZONES.len() > 400);
        assert_eq!(zones::TZDATA_VERSION, "2026c");
        assert!(zone_by_name("Europe/London").is_ok());
        assert!(zone_by_name("Mars/Olympus").is_err());
        let tok = zone_by_name("Asia/Tokyo").unwrap();
        assert_eq!(tok.std_offset, 9 * 3600);
        assert!(tok.dst.is_none());
    }

    #[test]
    fn chicago_dst_2026() {
        let z = chicago();
        // Spring forward: 2026-03-08 08:00:00 UTC (day 20520 + 8h).
        let start = 20_520 * 86_400 + 8 * 3600;
        let before = z.info_at(start - 1);
        assert_eq!((before.offset, before.is_dst), (-6 * 3600, false));
        let after = z.info_at(start);
        assert_eq!((after.offset, after.is_dst), (-5 * 3600, true));
        // Fall back: 2026-11-01 07:00:00 UTC (day 20758 + 7h).
        let end = 20_758 * 86_400 + 7 * 3600;
        assert_eq!(z.info_at(end - 1).offset, -5 * 3600);
        assert_eq!(z.info_at(end).offset, -6 * 3600);
        // Abbrs + civil:
        let (c, _, abbr) = z.to_local(start);
        assert_eq!(abbr, "CDT");
        assert_eq!((c.hour, c.minute), (3, 0));
    }

    #[test]
    fn gap_and_overlap() {
        let z = chicago();
        // 2026-03-08 02:30 does not exist.
        let gap = Civil {
            year: 2026,
            month: 3,
            day: 8,
            hour: 2,
            minute: 30,
            second: 0,
        };
        assert_eq!(z.from_local(gap, POLICY_REJECT).unwrap_err().0, ERR_GAP);
        let (t, flags) = z.from_local(gap, POLICY_EARLIER).unwrap();
        assert_eq!(flags, 1);
        let (back, _, _) = z.to_local(t);
        assert_eq!((back.hour, back.minute), (3, 30)); // shifted past the gap
                                                       // 2026-11-01 01:30 happens twice.
        let amb = Civil {
            year: 2026,
            month: 11,
            day: 1,
            hour: 1,
            minute: 30,
            second: 0,
        };
        assert_eq!(
            z.from_local(amb, POLICY_REJECT).unwrap_err().0,
            ERR_AMBIGUOUS
        );
        let (e, f1) = z.from_local(amb, POLICY_EARLIER).unwrap();
        let (l, f2) = z.from_local(amb, POLICY_LATER).unwrap();
        assert_eq!((f1, f2), (2, 2));
        assert_eq!(l - e, 3600);
        assert!(z.info_at(e).is_dst); // earlier = CDT occurrence
        assert!(!z.info_at(l).is_dst);
    }

    #[test]
    fn southern_hemisphere_and_fixed() {
        let syd = zone_by_name("Australia/Sydney").unwrap();
        // January: AEDT (+11, DST). July: AEST (+10).
        let jan = days_from_civil(2026, 1, 15) * 86_400;
        let jul = days_from_civil(2026, 7, 15) * 86_400;
        assert_eq!(
            syd.info_at(jan),
            ZoneInfo {
                offset: 11 * 3600,
                is_dst: true
            }
        );
        assert_eq!(
            syd.info_at(jul),
            ZoneInfo {
                offset: 10 * 3600,
                is_dst: false
            }
        );
        let tok = zone_by_name("Asia/Tokyo").unwrap();
        assert_eq!(tok.info_at(jan).offset, 9 * 3600);
        assert!(tok.next_transition(jan).is_none());
    }

    #[test]
    fn next_transition_and_arithmetic() {
        let z = chicago();
        let jan = days_from_civil(2026, 1, 15) * 86_400;
        let (t, after) = z.next_transition(jan).unwrap();
        assert_eq!(t, 20_520 * 86_400 + 8 * 3600);
        assert!(after.is_dst);
        // +1 month from Jan 31 12:00 local -> Feb 28 12:00 local (clamped).
        let jan31 = z
            .from_local(
                Civil {
                    year: 2026,
                    month: 1,
                    day: 31,
                    hour: 12,
                    minute: 0,
                    second: 0,
                },
                POLICY_EARLIER,
            )
            .unwrap()
            .0;
        let feb = add_calendar(&z, jan31, 0, 1, 0, 0).unwrap();
        let (c, _, _) = z.to_local(feb);
        assert_eq!((c.month, c.day, c.hour), (2, 28, 12));
    }

    #[test]
    fn iso_parse_and_format() {
        assert_eq!(parse_iso("1970-01-01T00:00:00Z").unwrap(), 0);
        assert_eq!(
            parse_iso("2026-10-20").unwrap(),
            days_from_civil(2026, 10, 20) * 86_400
        );
        assert_eq!(
            parse_iso("2026-10-20T15:15:30+02:00").unwrap(),
            parse_iso("2026-10-20T13:15:30Z").unwrap()
        );
        assert!(parse_iso("2026-13-01").is_err());
        let z = chicago();
        let t = parse_iso("2026-10-20T15:15:30Z").unwrap();
        assert_eq!(
            format(&z, t, "%Y-%m-%d %H:%M %Z %z"),
            "2026-10-20 10:15 CDT -0500"
        );
    }
}
